****：quantumcircuit，use qml.Displacement ， Wigner 。qml.Displacement PennyLane （ API ），use D(α)。use `default.gaussian` ，is Wigner 。use `qml.gradients.param_shift`，use。

```python
#!/usr/bin/env python3

def main():
    import pennylane as qml
    import numpy as np

    # use，
    dev = qml.device("default.gaussian", wires=1)

    @qml.qnode(dev)
    def wigner_circuit(alpha, x, p):
     qml.Displacement(alpha, wires=0)
     return qml.Wigner(wires=0, x_grid=[x], p_grid=[p])

    # use。note： alpha ，use。
    @qml.gradients.param_shift
    def wigner_grad(alpha, x, p):
     return wigner_circuit(alpha, x, p)

    # 
    alpha = 0.5 + 0.0j # ，
    x_vals = np.linspace(-2, 2, 10)
    p_vals = np.linspace(-2, 2, 10)
    X, P = np.meshgrid(x_vals, p_vals)

    # Wigner 
    W = np.zeros_like(X)
    for i in range(len(x_vals)):
     for j in range(len(p_vals)):
     W[i, j] = wigner_circuit(alpha, x_vals[i], p_vals[j])

    # （ alpha ）
    dW_dalpha = np.zeros_like(X, dtype=complex)
    alpha_complex = complex(alpha)
    # note：/， alpha
    grad_func = qml.grad(wigner_circuit, argnum=0) # use grad
    for i in range(len(x_vals)):
     for j in range(len(p_vals)):
     dW_dalpha[i, j] = grad_func(alpha, x_vals[i], p_vals[j])

    print("Wigner :", W.shape)
    print(":", dW_dalpha.shape)

    # 
    assert W.shape == (10, 10), "Wigner "
    print("circuit，。")

if __name__ == "__main__":
    main()
```

