    import pennylane as qml
    import numpy as np

    dev = qml.device('default.qubit', wires=3)

    @qml.qnode(dev)
    def circuit():
     qml.Hadamard(0)
     qml.Hadamard(1)
     qml.ControlledPhase(np.pi/3, wires=[0,1]) # Correct: two wires
     return qml.state()

    print(circuit())

if __name__ == "__main__":
    main()
